using System;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonItemsCareVerification
    {
        static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
        public static void BuildAndVerify()
        {
            PythonItemsLayout.Build();var p=UnityEngine.Object.FindObjectOfType<ContentPreview>();p.Initialize();var c=p.GetComponent<PythonStateClient>();var f=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(c,p);
            var state=PythonServiceSetup.Sample();state.instance_id="care-ui-test";state.can_set_shifts=true;state.required_action="";var first=state.cats[0];var target=state.cats[1];target.fatigue=35;target.stress=20;
            Func<PythonItemTarget[]> targets=()=>new[]{new PythonItemTarget{cat_id=first.cat_id,name=first.name,activity="在店",changes="ストレス 20 → 10",can_select=true},new PythonItemTarget{cat_id=target.cat_id,name=target.name,activity="在店",changes="疲労 35 → 25 / ストレス 20 → 10",can_select=true}};
            state.items=new PythonItems{count=3,shop=new[]{new PythonItemShop{choice="care_supplies",name="ケア用品",effect="ストレス −10",cost=100,funds_after=900,can_select=true}},owned=new[]{new PythonOwnedItem{choice="owned-1",name="ケア用品",count=2,effect="ストレス −10",price=40,funds_after=1040,can_sell=true,targets=targets()},new PythonOwnedItem{choice="owned-2",name="ケアセット",count=1,effect="疲労・ストレス −10",price=80,funds_after=1080,can_sell=true,targets=targets()}},history="1日目 ケア用品購入"};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(c,new object[]{state});apply();p.GetComponent<PythonPreparationPanel>().Close();var detail=p.GetComponent<PythonCatDetailsPanel>();var items=p.GetComponent<PythonItemsPanel>();detail.OpenFromList(target.cat_id,false);detail.care.onClick.Invoke();Check(items.cats.options[items.cats.value].text.Contains(target.name),"Detail target lost");Check(items.use.gameObject.activeSelf && !items.buy.gameObject.activeSelf && !items.sell.gameObject.activeSelf,"Care actions overlap");Check(items.details.text.Contains("疲労 35") && items.details.text.Contains("35 → 25"),"Before and after missing");items.owned.value=1;Check(items.cats.options[items.cats.value].text.Contains(target.name),"Changing item lost cat");apply();Check(items.cats.options[items.cats.value].text.Contains(target.name),"Polling lost cat");Check(items.panel.transform.GetSiblingIndex()==items.panel.transform.parent.childCount-1,"Polling covered care");
            items.use.onClick.Invoke();Check(items.confirmationText.text.Contains(target.name) && items.confirmationText.text.Contains("1 → 0"),"Care confirmation incorrect");items.cancel.onClick.Invoke();Check(typeof(PythonStateClient).GetField("pending",f).GetValue(c)==null,"Cancel sent action");Capture(p,"ItemsCare");
            items.modeTabs[1].onClick.Invoke();Check(items.shop.gameObject.activeSelf && items.buy.gameObject.activeSelf && !items.cats.gameObject.activeSelf && !items.use.gameObject.activeSelf,"Purchase layout incorrect");Check(items.details.text.Contains("900"),"Purchase funds missing");items.Buy();Check(items.confirmationText.text.Contains("100"),"Purchase confirmation missing");items.Cancel();Capture(p,"ItemsPurchase");
            items.modeTabs[2].onClick.Invoke();Check(items.sell.gameObject.activeSelf && !items.use.gameObject.activeSelf && items.details.text.Contains("1080"),"Sale layout incorrect");items.Sell();Check(items.confirmationText.text.Contains("1 → 0"),"Sale count missing");items.Cancel();items.ShowHistory();Check(items.details.text.Contains("1日目") && !items.buy.gameObject.activeSelf && !items.use.gameObject.activeSelf && !items.sell.gameObject.activeSelf && !items.owned.gameObject.activeSelf,"History tab exposes actions");Check(items.sectionLabel.text.Contains("所持 3個"),"Inventory summary missing");Check(items.details.GetComponentInParent<ScrollRect>().viewport.rect.height>300,"History area not expanded");Capture(p,"ItemsHistory");items.ShowCare();Check(items.details.GetComponentInParent<ScrollRect>().viewport.rect.height<230,"Care layout not restored");Check(!items.details.text.Contains("1日目"),"History mixed with care");state.items.owned[1].targets[1].can_select=false;state.items.owned[1].targets[1].reason="派遣中の猫には使用できません。";state.revision++;apply();Check(!items.use.interactable && items.details.text.Contains("派遣中の猫には"),"Unavailable reason missing");items.close.onClick.Invoke();Check(!items.panel.activeSelf && detail.panel.activeSelf && detail.title.text.Contains(target.name),"Care return lost same detail");
            detail.care.onClick.Invoke();items.ShowPurchase();state.revision++;apply();Check(items.buy.gameObject.activeSelf,"Polling reset mode");items.Buy();state.revision++;apply();Check(!items.confirmation.activeSelf,"Revision retained confirmation");items.Disconnect();Check(!items.buy.interactable && !items.modeTabs[0].interactable,"Offline controls enabled");apply();items.Close();detail.Close();items.Open();Check(items.close.GetComponentInChildren<Text>().text=="閉じる","Menu retained detail return");state.items.owned=new PythonOwnedItem[0];state.revision++;apply();Check(!items.use.interactable && items.details.text.Contains("所持品はありません"),"Empty inventory incorrect");items.ShowPurchase();state.items.shop[0].can_select=false;state.items.shop[0].reason="営業中は購入できません。";state.revision++;apply();Check(!items.buy.interactable && items.details.text.Contains("営業中は"),"Purchase reason missing");
            state.items.shop[0].can_select=true;state.items.shop[0].reason="";state.items.shop[0].ends_game=true;state.items.shop[0].funds_after=0;state.revision++;apply();items.Buy();Check(items.confirmationText.text.Contains("営業が終了"),"Zero funds guard missing");items.Cancel();state.instance_id="new-game";apply();Check(!items.panel.activeSelf,"New game retained care");
            state.items.owned=new[]{new PythonOwnedItem{choice="owned-command",name="ケア用品",count=1,targets=targets()}};state.items.owned[0].targets[1].can_select=true;state.revision++;apply();detail.OpenFromList(target.cat_id,false);detail.Care();items.Use();items.Confirm();var command=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(c);Check(command!=null && command.kind=="use_item" && command.choice=="owned-command" && command.cat_id==target.cat_id,"Care sent wrong target");Check(!items.use.interactable,"Pending allowed duplicate use");items.ShowHistory();Check(items.use.gameObject.activeSelf,"Pending allowed direct tab switch");Debug.Log("CAT_CAFE_ITEMS_CARE_UI_OK: cat / tabs / changes / reasons / polling / return / confirm / cancel / offline / empty / reset / command");
        }
        static void Capture(ContentPreview p,string name){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{p,"Logs/"+name+".png"});}
    }
}
